(function executeRule(current, previous) {

    if (current.source_table != 'x_birl3_clm_clm_new_credit_request')
        return;

    var req = new GlideRecord('x_birl3_clm_clm_new_credit_request');
    if (!req.get(current.document_id))
        return;

    var initiator = req.getValue('initiator');
    var segment   = req.getValue('segment');

    var firstApprover = '';
    if (segment == 'Cement') firstApprover = req.getValue('u_approver_tsh');
    else if (segment == 'RMC') firstApprover = req.getValue('u_approver_tsm');
    else if (segment == 'BPD') firstApprover = req.getValue('u_approver_tsh_bpd');

    if (!firstApprover || initiator != firstApprover)
        return;

    if (current.approver.toString() != firstApprover)
        return;

    current.setWorkflow(false);
    current.state = 'approved';
    current.comments = 'Auto Approved by TSH.';
    current.update();

    // NEW: keep the parent request's "approved amount" in sync so the
    // next approver's "Previous Approved Limit" card isn't blank/₹0.
    // Auto-approve implies no override — the implicit approved figure
    // is simply the code-level requested total for Trade.
    if ((req.customer_type + '') === 'Trade') {
        var codeLevelTotal = parseFloat(req.getValue('u_code_level_total_requested')) || 0;
        if (!parseFloat(req.getValue('u_approved_code_limit'))) {
            req.setValue('u_approved_code_limit', codeLevelTotal);
            req.setValue('approved_limit', codeLevelTotal);
            req.setWorkflow(false);
            req.autoSysFields(false);
            req.update();
        }
    }

    gs.info(
        'CLM Auto Approval: Approval auto-approved for request ' +
        req.getValue('request_number')
    );
	new CLMApprovalLimit().save(requestSysId, approvalRecordSysId, limitValue);

})(current, previous);
